module exam_helper (\n    input clk,\n    input rst_n,\n    input valid_in,\n    input op,\n    input [31:0] A_in,\n    input [31:0] B_in,\n    input [3:0] idx_in,\n    output reg valid_out,\n    output reg [31:0] result\n);\n\n    parameter MAX_STUDENTS = 16;\n    reg [31:0] A_reg [0:MAX_STUDENTS-1];\n    reg [31:0] B_reg [0:MAX_STUDENTS-1];\n    reg [4:0] count;\n    \n    reg [3:0] candidate_index;\n    reg candidate_found;\n    reg [31:0] candidate_B_diff;\n    reg [31:0] candidate_A_diff;\n    integer j;\n    \n    always @(*) begin\n        candidate_index = 4'd0;\n        candidate_found = 1'b0;\n        candidate_B_diff = 32'hFFFF_FFFF;\n        candidate_A_diff = 32'hFFFF_FFFF;\n        \n        if (idx_in >= 4'd1 && idx_in <= count[3:0]) begin\n            if (count > 5'd0) begin\n                for (j = 0; j < MAX_STUDENTS; j = j + 1) begin\n                    if (j < count && j != (idx_in-4'd1)) begin\n                        if (A_reg[j] >= A_reg[idx_in-4'd1] && B_reg[j] >= B_reg[idx_in-4'd1]) begin\n                            if ((B_reg[j] - B_reg[idx_in-4'd1]) < candidate_B_diff || \n                                ((B_reg[j] - B_reg[idx_in-4'd1]) == candidate_B_diff && \n                                 (A_reg[j] - A_reg[idx_in-4'd1]) < candidate_A_diff)) begin\n                                candidate_index = j[3:0];\n                                candidate_B_diff = B_reg[j] - B_reg[idx_in-4'd1];\n                                candidate_A_diff = A_reg[j] - A_reg[idx_in-4'd1];\n                                candidate_found = 1'b1;\n                            end\n                        end\n                    end\n                end\n            end\n        end\n    end\n    \n    integer i;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            count <= 5'd0;\n            valid_out <= 1'b0;\n            result <= 32'd0;\n            for (i = 0; i < MAX_STUDENTS; i = i + 1) begin\n                A_reg[i] <= 32'd0;\n                B_reg[i] <= 32'd0;\n            end\n        end else begin\n            valid_out <= 1'b0;\n            \n            if (valid_in) begin\n                if (op == 1'b0) begin  // D operation\n                    if (count < 5'd16) begin\n                        A_reg[count] <= A_in;\n                        B_reg[count] <= B_in;\n                        count <= count + 5'd1;\n                    end\n                end else begin  // P operation\n                    result <= candidate_found ? {28'd0, candidate_index + 4'd1} : 32'd0;\n                    valid_out <= 1'b1;\n                end\n            end\n        end\n    end\n\nendmodule